INSERT INTO converted_files (title, description, file_url, file_name, s3_key, size_bytes) VALUES ('УПД Трейд Ресурс 12.10 КБТ в загрузку', 'УПД ООО «ВГ-ТРЕЙД» (Weissgauff) № 261012002/2 от 12.10.2026 по правилу «Создание файла для OData». Восемь колонок: Артикул (из «Код товара», текстом), Штрихкод (в УПД нет — пусто), Наименование (как в УПД), Количество, Цена с НДС, Страна, Номер ГТД, Номер РНПТ. 175 строк, 212 шт, 2 570 524,80 руб. — сходится с «Всего к оплате» до копейки. ГТД в 91 строке, РНПТ в 69 (по признаку прослеживаемости), в 15 строках номера декларации нет в самом УПД (белорусские плиты, духовые шкафы, холодильники), у 6 из них нет и страны.', '/converted/upd-treid-resurs-12-10-kbt-v-zagruzku.xlsx', 'УПД Трейд Ресурс 12.10 КБТ в загрузку.xlsx', 'converted/upd-treid-resurs-12-10-kbt-v-zagruzku.xlsx', 15378);